245	  ctx.call('statuses', orderId, { op: 'init', orderId, fulfilments: state.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location })) });
246	  ctx.call('notices', orderId, { op: 'init', customerId: state.customerId });
247	  ctx.call('fraud', orderId, { op: 'start', orderId, placedAt: state.placedAt, edition: state.edition });
248	  const ca = ctx.call('customer-action', orderId, { op: 'start', orderId, placedAt: state.placedAt, edition: state.edition,
249	    fulfilments: state.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available })) });
250	  state.phase = 'fraud';
251	  state.busy.ca = ca.busy;
252	  const held = state.held;
253	  state.held = [];
254	  for (const h of held) {
255	    if (h.action === 'cancel') {
256	      const v = ctx.call('cancellation', orderId, { op: 'customer-cancel', orderId, at: h.at, eventId: h.eventId, phase: 'not-cleared',
257	        fulfilmentIds: state.fulfilments.filter(f => f.available).map(f => f.fulfilmentId) });
258	      verdictOf(v, state, ctx);
259	    } else if (state.phase === 'fraud') {
260	      onModuleOutput('customer-action', orderId, ctx.call('customer-action', orderId, { op: 'action', action: h.action, at: h.at }), state, ctx);
261	    }
262	    if (state.phase === 'ended') break;
263	  }
264	}
265	
266	function onFraud(out, state, ctx) {
267	  state.busy.fraud = out.busy;
268	  if (state.phase !== 'fraud') return;
269	  const orderId = state.orderId;
270	  if (out.state === 'cleared') {
271	    // R2.1: cleared at c. R3.1 for unavailable items, else ready at c (R4.1).
272	    const ca = ctx.call('customer-action', orderId, { op: 'advance', clearedAt: out.at });
273	    state.busy.ca = ca.busy;
274	    if (ca.state === 'waiting') {
275	      state.phase = 'waiting';
276	      return;
277	    }
278	    return becomeReady(out.at, state, ctx);                                      // ready (counted amend) or no unavailable items
279	  }
280	  if (out.state === 'cancel') {
281	    // R2.1, R2.2: the order is cancelled for fraud or by the review deadline (S15).
282	    const v = ctx.call('cancellation', orderId, { op: 'cancel-order', orderId, at: out.at, reason: out.reason });
283	    endOrder(state, ctx);
284	    return v;
285	  }
286	}
287	
288	function onCustomerAction(out, state, ctx) {
289	  state.busy.ca = out.busy;
290	  const orderId = state.orderId;
291	  if (state.phase === 'waiting' && out.state === 'ready') return becomeReady(out.at, state, ctx);   // R3.2: counted amend
292	  if ((state.phase === 'waiting' || state.phase === 'fraud') && out.state === 'cancel') {
293	    ctx.call('cancellation', orderId, { op: 'cancel-order', orderId, at: out.at, reason: out.reason });
294	    endOrder(state, ctx);
295	    return;
296	  }
297	  if ((state.phase === 'waiting' || state.phase === 'fraud') && out.state === 'timedOut') {
298	    endOrder(state, ctx);                                                        // R3.2: the end of the order
299	    return;
300	  }
301	}
302	
303	function becomeReady(at, state, ctx) {
304	  state.phase = 'processing';
305	  state.readyAt = at;
306	}
307	
308	function onFulfilment(fid, out, state, ctx) {
309	  state.busy[`f:${fid}`] = out.busy;
310	  const saga = state.sagas[fid] ?? { end: null, reported: false };
311	  if (out.end) saga.end = out.end;
312	  state.sagas[fid] = saga;
313	  if (FULFILMENT_ENDS.includes(out.end) && !saga.reported && state.phase === 'processing') {
314	    saga.reported = true;
315	    const r = ctx.call('order-progress', state.orderId, { op: 'ended', orderId: state.orderId, fulfilmentId: fid, end: out.end, at: out.endedAt });
316	    if (r.state === 'ended') state.phase = 'ended';
317	  }
318	}
319	
320	// ---------------------------------------------------------------------------------------------------------------------
321	// End of tick: the only place where forward steps are emitted (S10). Nothing once the order has ended (S9, R6.2).
322	
323	function endOfTick(state, input, ctx) {
324	  const orderId = state.orderId;
325	  if (!state.readyDone) {
326	    state.readyDone = true;
327	    ctx.call('order-progress', orderId, { op: 'ready', orderId, at: state.readyAt, fulfilments: state.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available })) });
328	  }
329	  for (const f of state.fulfilments) {
330	    if (!f.available) continue;
331	    const saga = state.sagas[f.fulfilmentId] ?? { end: null, reported: false };
332	    if (saga.end) continue;
333	    if (!state.started[f.fulfilmentId]) {
334	      state.started[f.fulfilmentId] = true;
335	      ctx.call('fulfilment', f.fulfilmentId, { op: 'start', orderId, customerId: state.customerId, currency: state.currency,
336	        edition: state.edition, fulfilment: { fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor } });
337	    }
338	    onFulfilment(f.fulfilmentId, ctx.call('fulfilment', f.fulfilmentId, { op: 'advance' }), state, ctx);
339	  }
340	}
341	
342	function shouldClose(state) {
343	  // Close only when the order has ended, no module is busy (R7.1) and every saga has ended. Until then the instance
344	  // stays open, so carrier messages quoting our ref still reach it (§1 Routing).
345	  if (state.phase !== 'ended') return false;
346	  if (Object.values(state.busy).some(Boolean)) return false;
347	  return Object.keys(state.started).every(fid => state.sagas[fid] && state.sagas[fid].end !== null);
348	}
349	
350	// ---------------------------------------------------------------------------------------------------------------------
351	// Helpers
352	
353	function normalise(raw, ctx) {
354	  return ctx.call('order-id', 'n', { raw }).orderId;
355	}
356	
357	function openElsewhere(orderId, input, ctx) {
358	  if (!orderId) return null;
359	  const list = ctx.instances({ subject: orderId }) ?? [];
360	  for (const x of list) {
361	    const id = typeof x === 'string' ? x : x?.instance ?? x?.id;
362	    if (id && id !== input.instance) return id;
363	  }
364	  return null;
365	}
366	
367	function recordedOrder(orderId, ctx) {
368	  return (ctx.query('orders.orders', { where: { orderId }, limit: 1 }) ?? []).length > 0;
369	}
370	
371	function orderOfFulfilment(fid, ctx) {
372	  if (!fid) return null;
373	  const row = (ctx.query('orders.fulfilments', { where: { fulfilmentId: fid }, limit: 1 }) ?? [])[0];
374	  return row ? row.orderId : null;
375	}
376

