1	// Module fulfilment, key: the fulfilment id. One saga per fulfilment. Owns R4.2 (reserve, charge, ship, in that order,
2	// each after the previous one committed), R4.3 (collection is the point of no return: a cancel is refused after it),
3	// R4.4 (carrier reports), R5.1 (compensation in reverse order of committed steps), R5.2 (failure), S2 (committed =
4	// result ok, or outcome unknown and status(key) committed) and S14 (a step committing after a failure or a stop is
5	// compensated when it commits). Forward steps are emitted only by `advance`, at the end of a tick (S10).
6	// Effects: inventory.reserve (`reserve-<n>`, items `item.<sku>`), billing.charge (`charge`), carrier.create (`ship`),
7	// carrier.cancel (`unship`), billing.refund (`refund`), inventory.release (`release.<sku>`). Calls statuses, notices.
8	// Always return `output`.
9	//
10	// state: { orderId, fid, customerId, currency, edition, location, items: [{sku, qty}], amountMinor, phase,
11	//          batches, reserve: { [sku]: 'pending'|'ok'|'failed'|'released' }, charge, ship, shipUndo, refund,
12	//          collectionFailed, dispatched, reports: [{ meaning, reportedAt }], end, endedAt }
13	//   phase: 'new' | 'running' | 'dispatched' | 'completed' | 'failed' | 'stopped'
14	//   charge / ship / refund: 'none' | 'pending' | 'ok' | 'failed' ; shipUndo, refund undo: 'none'|'pending'|'done'
15	
16	const MAX_BATCHES = 5;
17	const MEANINGS = ['collected', 'inTransit', 'delivered', 'collectionFailed'];
18	
19	// Files arrive as raw text: parse a JSON file (or pass a parsed value through).
20	function fileJson(files, path) {
21	  const v = files?.[path];
22	  return typeof v === 'string' ? JSON.parse(v) : v ?? null;
23	}
24	
25	export function step(input, ctx) { return withFit(stepOf(input, ctx), ctx); }
26	
27	function stepOf(input, ctx) {
28	  switch (input.op) {
29	    case 'start': return start(input, ctx);
30	    case 'advance': return advance(input, ctx);
31	    case 'carrier': return carrier(input, ctx);
32	    case 'stop': return stop(input, ctx);
33	    case 'get': return { output: view(ctx.state) };
34	    case 'resume': return resume(input, ctx);
35	  }
36	  throw new Error(`fulfilment: unknown op ${input.op}`);
37	}
38	
39	export function onEvent(event, ctx) { return withFit(eventOf(event, ctx), ctx); }
40	
41	function eventOf(event, ctx) {
42	  const state = ctx.state;
43	  if (!state) return { output: view(null) };
44	  if (event.type !== 'effect.result') return { output: view(state) };
45	  const p = event.payload ?? {};
46	  const r = resultOf(p);
47	  if (p.key === 'charge') return chargeResult(state, r, ctx);
48	  if (p.key === 'ship') return shipResult(state, r, ctx);
49	  if (p.key === 'unship' || p.key === 'refund' || (typeof p.key === 'string' && p.key.startsWith('release.'))) {
50	    return undoResult(state, p, r, ctx);
51	  }
52	  if (p.system === 'inventory' && p.op === 'reserve') return reserveResult(state, p, r, ctx);
53	  throw new Error(`fulfilment: unexpected effect result ${JSON.stringify(p).slice(0, 160)}`);
54	}
55	
56	function view(state) {
57	  if (!state) return { state: 'idle', end: null, endedAt: null, reports: [], busy: false };
58	  return {
59	    state: state.phase, end: state.end ?? null, endedAt: state.endedAt ?? null,
60	    reports: state.reports, busy: busy(state),
61	  };
62	}
63	
64	function busy(s) {
65	  if (s.charge === 'pending' || s.ship === 'pending' || s.shipUndo === 'pending' || s.refund === 'pending') return true;
66	  return Object.values(s.reserve ?? {}).includes('pending');
67	}
68	
69	// ---------------------------------------------------------------------------------------------------------------------
70	// Start and forward steps
71	
72	function start(input, ctx) {
73	  const items = mergeItems(input.fulfilment.items);
74	  const state = {
75	    orderId: input.orderId, fid: input.fulfilment.fulfilmentId, customerId: input.customerId, currency: input.currency,
76	    edition: input.edition, location: input.fulfilment.location, items, amountMinor: input.fulfilment.amountMinor,
77	    phase: 'running', batches: 0,
78	    reserve: Object.fromEntries(items.map(i => [i.sku, 'none'])),
79	    charge: 'none', ship: 'none', shipUndo: 'none', refund: 'none', collectionFailed: false, dispatched: false,
80	    reports: [], end: null, endedAt: null,
81	  };
82	  return { output: view(state), state };
83	}
84	
85	function advance(input, ctx) {
86	  const state = ctx.state;
87	  if (!state) return { output: view(null) };
88	  if (state.phase === 'failed' || state.phase === 'stopped') return compensate(state, ctx);
89	  if (state.phase !== 'running' && state.phase !== 'dispatched') return { output: view(state) };
90	  const effects = [];
91	  const s = { ...state, reserve: { ...state.reserve } };
92	  // Step 1: reserve every item, as one batch (R4.2).
93	  const emptyReserve = Object.values(s.reserve).every(v => v === 'none');
94	  if (emptyReserve) {
95	    const items = s.items.map(i => ({ key: `item.${i.sku}`, sku: i.sku, qty: i.qty }));
96	    for (const i of s.items) s.reserve[i.sku] = 'pending';
97	    s.batches = 1;
98	    effects.push(reserveEffect(s, items));
99	  }
100	  // Step 2: charge once every reservation committed (R4.2).
101	  if (s.charge === 'none' && Object.values(s.reserve).every(v => v === 'ok')) {
102	    s.charge = 'pending';
103	    effects.push({ key: 'charge', system: 'billing', op: 'charge', args: {
104	      orderId: s.orderId, fulfilmentId: s.fid, customerId: s.customerId, amountMinor: s.amountMinor, currency: s.currency,
105	    } });
106	  }
107	  // Step 3: book the shipment once the charge committed (R4.2), with the fulfilment id as the carrier ref.
108	  if (s.charge === 'ok' && s.ship === 'none') {
109	    s.ship = 'pending';
110	    effects.push({ key: 'ship', system: 'carrier', op: 'create', args: {
111	      orderId: s.orderId, fulfilmentId: s.fid, location: s.location, ref: s.fid,
112	    } });
113	  }
114	  if (effects.length === 0) return { output: view(state) };
115	  return { output: view(s), state: s, effects };
116	}
117	
118	// A batch op keys its items, not the batch (§2): the item keys are the idempotency keys.
119	function reserveEffect(s, items) {
120	  return { system: 'inventory', op: 'reserve', args: { orderId: s.orderId, fulfilmentId: s.fid, location: s.location, items } };
121	}
122	
123	function mergeItems(items) {
124	  const bySku = new Map();
125	  for (const i of items) bySku.set(i.sku, (bySku.get(i.sku) ?? 0) + i.qty);
126	  return [...bySku].map(([sku, qty]) => ({ sku, qty }));
127	}
128	
129	// ---------------------------------------------------------------------------------------------------------------------
130	// Results of forward steps
131	
132	function reserveResult(state, p, r, ctx) {
133	  const s = { ...state, reserve: { ...state.reserve } };
134	  const outcome = {};
135	  if (r.status === 'ok') {
136	    for (const sku of Object.keys(s.reserve)) if (s.reserve[sku] === 'pending') outcome[sku] = 'ok';
137	  } else if (r.status === 'partial' || Array.isArray(p.items)) {
138	    for (const it of p.items ?? []) {
139	      const sku = String(it.key ?? '').replace(/^item\./, '');
140	      if (!(sku in s.reserve)) continue;
141	      if (it.status === 'ok') outcome[sku] = 'ok';
142	      else outcome[sku] = it.error?.retryable === false || it.retryable === false ? 'failed-permanent' : 'failed';
143	    }
144	  } else if (isInvalidRequest(r)) {
145	    // R4.2: a 400 is our own mistake: correct and re-issue with the same key, inside the window (not a failure).
146	    return reissueReserve(s, p, ctx);
147	  } else if (r.status === 'error' && r.retryable === false) {
148	    for (const sku of Object.keys(s.reserve)) if (s.reserve[sku] === 'pending') s.reserve[sku] = 'failed';
149	    return fail(s, ctx, 'reserve-error', ctx.now);
150	  } else {
151	    throw new Error(`fulfilment: unexpected reserve result ${JSON.stringify(p).slice(0, 160)}`);
152	  }
153	  for (const [sku, v] of Object.entries(outcome)) {
154	    if (v === 'ok') s.reserve[sku] = 'ok';
155	  }
156	  const permanent = Object.values(outcome).includes('failed-permanent');
157	  const failed = Object.keys(outcome).filter(sku => outcome[sku] === 'failed').concat(Object.keys(s.reserve).filter(sku => s.reserve[sku] === 'pending' && !(sku in outcome)));
158	  if (permanent) {
159	    for (const sku of Object.keys(s.reserve)) if (s.reserve[sku] === 'pending') s.reserve[sku] = 'failed';
160	    return fail(s, ctx, 'reserve-error', ctx.now);
161	  }
162	  if (failed.length === 0) return afterStep(s, ctx);
163	  if (s.phase === 'stopped' || s.phase === 'failed') {
164	    for (const sku of failed) s.reserve[sku] = 'failed';
165	    return compensate(s, ctx);                                          // nothing new after a stop or a failure
166	  }
167	  // A partial batch is delivered, not retried: resubmit only the failed items, with their original keys (R4.2).
168	  if (s.batches >= MAX_BATCHES) {
169	    for (const sku of failed) s.reserve[sku] = 'failed';
170	    return fail(s, ctx, 'reserve-error', ctx.now);
171	  }
172	  s.batches += 1;
173	  const items = s.items.filter(i => failed.includes(i.sku)).map(i => ({ key: `item.${i.sku}`, sku: i.sku, qty: i.qty }));
174	  for (const sku of failed) s.reserve[sku] = 'pending';
175	  return { output: view(s), state: s, effects: [reserveEffect(s, items)] };
176	}
177	
178	// After a result, forward steps that became due are emitted by advance (or here, at once when the saga moves on).
179	function afterStep(s, ctx) {
180	  const next = advance({}, { ...ctx, state: s });
181	  return next.state ? next : { output: view(s), state: s };
182	}
183	
184	function reissueReserve(s, p, ctx) {
185	  if (s.phase === 'stopped' || s.phase === 'failed') {
186	    for (const sku of Object.keys(s.reserve)) if (s.reserve[sku] === 'pending') s.reserve[sku] = 'failed';
187	    return compensate(s, ctx);
188	  }
189	  const items = s.items.filter(i => s.reserve[i.sku] === 'pending').map(i => ({ key: `item.${i.sku}`, sku: i.sku, qty: i.qty }));
190	  return { output: view(s), state: s, effects: [reserveEffect(s, items)] };
191	}
192	
193	function chargeResult(state, r, ctx) {
194	  const s = { ...state };
195	  if (r.status === 'ok') { s.charge = 'ok'; return afterStepOrCompensate(s, ctx); }
196	  if (isInvalidRequest(r)) return reissueCharge(s, ctx);
197	  if (isDeclined(r) || r.status === 'error' || r.status === 'unknown') {
198	    if (r.status === 'unknown' && ctx.status('billing', 'charge') === 'committed') { s.charge = 'ok'; return afterStepOrCompensate(s, ctx); }
199	    s.charge = 'failed';
200	    return fail(s, ctx, isDeclined(r) ? 'card-declined' : 'charge-error', ctx.now);
201	  }
202	  throw new Error(`fulfilment: unexpected charge result ${JSON.stringify(r).slice(0, 160)}`);
203	}
204	
205	function reissueCharge(s, ctx) {
206	  if (s.phase === 'stopped' || s.phase === 'failed') { s.charge = 'failed'; return compensate(s, ctx); }
207	  return { output: view(s), state: s, effects: [{ key: 'charge', system: 'billing', op: 'charge', args: {
208	    orderId: s.orderId, fulfilmentId: s.fid, customerId: s.customerId, amountMinor: s.amountMinor, currency: s.currency,
209	  } }] };
210	}
211	
212	function shipResult(state, r, ctx) {
213	  const s = { ...state };
214	  if (r.status === 'ok') { s.ship = 'ok'; return afterStepOrCompensate(s, ctx); }
215	  if (isInvalidRequest(r)) {
216	    if (s.phase === 'stopped' || s.phase === 'failed') { s.ship = 'failed'; return compensate(s, ctx); }
217	    return { output: view(s), state: s, effects: [{ key: 'ship', system: 'carrier', op: 'create', args: {
218	      orderId: s.orderId, fulfilmentId: s.fid, location: s.location, ref: s.fid,
219	    } }] };
220	  }
221	  if (r.status === 'unknown' && ctx.status('carrier', 'ship') === 'committed') { s.ship = 'ok'; return afterStepOrCompensate(s, ctx); }
222	  if (r.status === 'error' || r.status === 'unknown') {
223	    s.ship = 'failed';
224	    return fail(s, ctx, 'ship-error', ctx.now);
225	  }
226	  throw new Error(`fulfilment: unexpected ship result ${JSON.stringify(r).slice(0, 160)}`);
227	}
228	
229	function afterStepOrCompensate(s, ctx) {
230	  // S14: a step that commits after the fulfilment failed or was stopped is compensated now.
231	  if (s.phase === 'failed' || s.phase === 'stopped') return compensate(s, ctx);
232	  return afterStep(s, ctx);
233	}
234	
235	function undoResult(state, p, r, ctx) {
236	  const s = { ...state };
237	  if (p.key === 'unship') s.shipUndo = 'done';
238	  if (p.key === 'refund') s.refund = 'ok';
239	  if (typeof p.key === 'string' && p.key.startsWith('release.')) {
240	    const sku = p.key.slice('release.'.length);
241	    if (sku in s.reserve) s.reserve[sku] = 'released';
242	  }
243	  return { output: view(s), state: s };
244	}
245	
246	// ---------------------------------------------------------------------------------------------------------------------
247	// Failure and compensation (R5.1, R5.2, S14)
248	
249	function fail(s, ctx, reason, at) {
250	  if (s.phase === 'failed' || s.phase === 'stopped') return compensate(s, ctx);
251	  s.phase = 'failed';
252	  s.end = 'failed';
253	  s.endedAt = at;
254	  s.failReason = reason;
255	  const undo = compensate(s, ctx);
256	  const fs = { ...undo.state };
257	  const effects = [...(undo.effects ?? [])];
258	  const orderId = s.orderId;
259	  ctx.call('statuses', orderId, { op: 'set', orderId, fulfilmentId: s.fid, status: 'failed' });
260	  ctx.call('notices', orderId, { op: 'send', template: 'fulfilment-failed', about: s.fid });
261	  return { output: view(fs), state: fs, effects };
262	}
263	
264	// Undo every committed step that is not undone yet, in reverse order: shipment, charge, reserved items (R5.1).
265	// Never undoes a step that did not commit, and never undoes one twice (the flags say which).
266	function compensate(state, ctx) {
267	  const s = { ...state, reserve: { ...state.reserve } };
268	  const effects = [];
269	  if (s.ship === 'ok' && s.shipUndo === 'none' && !s.collectionFailed) {
270	    s.shipUndo = 'pending';
271	    effects.push({ key: 'unship', system: 'carrier', op: 'cancel', args: { orderId: s.orderId, fulfilmentId: s.fid } });
272	  }
273	  if (s.charge === 'ok' && s.refund === 'none') {
274	    s.refund = 'pending';
275	    effects.push({ key: 'refund', system: 'billing', op: 'refund', args: { orderId: s.orderId, fulfilmentId: s.fid, amountMinor: s.amountMinor } });
276	  }
277	  for (const i of s.items) {
278	    if (s.reserve[i.sku] === 'ok') {
279	      s.reserve[i.sku] = 'released';
280	      effects.push({ key: `release.${i.sku}`, system: 'inventory', op: 'release', args: { orderId: s.orderId, fulfilmentId: s.fid, sku: i.sku } });
281	    }
282	  }
283	  if (effects.length === 0) return { output: view(s), state: s };
284	  return { output: view(s), state: s, effects };
285	}
286	
287	// ---------------------------------------------------------------------------------------------------------------------
288	// Carrier reports (R4.4, §3.3)
289	
290	function carrier(input, ctx) {
291	  const s = { ...ctx.state, reports: [...(ctx.state?.reports ?? [])] };
292	  if (!ctx.state) return { output: view(null) };
293	  const meaning = meaningOf(ctx, input.message);
294	  const at = input.message.reportedAt;
295	  if (MEANINGS.includes(meaning) && !s.reports.some(x => x.meaning === meaning && x.reportedAt === at)) {
296	    s.reports.push({ meaning, reportedAt: at });
297	  }
298	  if (s.phase !== 'running' && s.phase !== 'dispatched') return { output: view(s), state: s };   // ended: changes nothing
299	  if (meaning === 'collected') {
300	    if (s.phase !== 'running' || s.ship !== 'ok') return { output: view(s), state: s };
301	    return dispatch(s, ctx, false);
302	  }
303	  if (meaning === 'delivered') {
304	    if (s.ship !== 'ok') return { output: view(s), state: s };
305	    return complete(s, ctx, at);
306	  }
307	  if (meaning === 'collectionFailed') {
308	    s.collectionFailed = true;
309	    if (s.phase !== 'running') return { output: view(s), state: s };
310	    return fail(s, ctx, 'collection-failed', at);
311	  }
312	  return { output: view(s), state: s };
313	}
314	
315	function meaningOf(ctx, message) {
316	  const table = fileJson(ctx.files, `rulebook/${ctx.state.edition}/carrier-codes.json`) ?? [];
317	  const row = table.find(r => r.carrier === message.carrier && r.code === message.code);
318	  return row ? row.meaning : 'info';
319	}
320	
321	function dispatch(s, ctx) {
322	  s.phase = 'dispatched';
323	  s.dispatched = true;
324	  ctx.call('statuses', s.orderId, { op: 'set', orderId: s.orderId, fulfilmentId: s.fid, status: 'dispatched' });
325	  return { output: view(s), state: s };
326	}
327	
328	function complete(s, ctx, at) {
329	  const effects = [];
330	  const fromDispatch = s.dispatched;
331	  s.phase = 'completed';
332	  s.end = 'completed';
333	  s.endedAt = at;
334	  ctx.call('statuses', s.orderId, { op: 'set', orderId: s.orderId, fulfilmentId: s.fid, status: 'completed', afterStatus: fromDispatch ? undefined : 'dispatched' });
335	  return { output: view(s), state: s, effects };
336	}
337	
338	// ---------------------------------------------------------------------------------------------------------------------
339	// Stop (a counted customer cancel, R6.2): no new step; compensate what committed; later commits compensated (S14)
340	
341	function stop(input, ctx) {
342	  const state = ctx.state;
343	  if (!state) return { output: view({ phase: 'stopped', reports: [] }) };
344	  if (state.phase === 'completed' || state.phase === 'failed') return { output: view(state) };
345	  const s = { ...state, phase: 'stopped', end: 'stopped', endedAt: input.at };
346	  return compensate(s, ctx);
347	}
348	
349	function resume(input, ctx) {
350	  // §3.5: a migrated fulfilment continues from its records.
351	  const r = input.records ?? {};
352	  if (!r.phase) return { output: view(ctx.state) };
353	  const state = { ...r };
354	  return { output: view(state), state };
355	}
356	
357	// ---------------------------------------------------------------------------------------------------------------------
358	
359	// An error is { code: <http status>, reason: <name>, retryable }.
360	function resultOf(p) {
361	  const error = p.error ?? null;
362	  return {
363	    status: p.status,
364	    code: error?.reason ?? null,
365	    retryable: error?.retryable ?? p.retryable ?? null,
366	    http: typeof error?.code === 'number' ? error.code : null,
367	  };
368	}
369	
370	const isInvalidRequest = r => r.http === 400 || r.code === 'invalid-args' || r.code === 'field-renamed';
371	const isDeclined = r => r.http === 402 || r.code === 'card-declined';
372	
373	// Args follow the system's current schema (api/<system>.schema.json, which always shows the current names): a field the
374	// system renamed is sent under its new name, so the call is not refused with 400 field-renamed (R4.2).
375	function withFit(res, ctx) {
376	  if (res && Array.isArray(res.effects)) {
377	    res.effects = res.effects.map(e => ({ ...e, args: fitObject(argsSchema(ctx.files, e.system, e.op), e.args) }));
378	  }
379	  return res;
380	}
381	
382	function argsSchema(files, system, op) {
383	  const api = fileJson(files, `api/${system}.schema.json`);
384	  return api?.ops?.[op]?.args ?? null;
385	}
386	
387	function fitObject(schema, obj) {
388	  if (!schema || !schema.properties || !obj || typeof obj !== 'object') return obj;
389	  const props = schema.properties;
390	  const free = Object.keys(props).filter(k => !(k in obj));
391	  const out = {};
392	  for (const [k, v] of Object.entries(obj)) {
393	    if (k in props) { out[k] = fitValue(props[k], v); continue; }
394	    const target = pickRename(k, free);
395	    if (target) { out[target] = fitValue(props[target], v); free.splice(free.indexOf(target), 1); } else out[k] = v;
396	  }
397	  return out;
398	}
399	
400	function fitValue(sch, v) {
401	  if (Array.isArray(v) && sch && sch.items && sch.items.properties) return v.map(x => fitObject(sch.items, x));
402	  return v;
403	}
404	
405	function pickRename(k, free) {
406	  const norm = x => x.toLowerCase().replace(/[^a-z0-9]/g, '');
407	  const nk = norm(k);
408	  const exact = free.find(f => norm(f) === nk);
409	  if (exact) return exact;
410	  const similar = free.filter(f => norm(f).includes(nk) || nk.includes(norm(f)));
411	  if (similar.length === 1) return similar[0];
412	  return free.length === 1 ? free[0] : null;
413	}
